        result = list(state)
        for i, code in enumerate(state):
            p, stage = divmod(code, 3)
            at, target, _, _ = self.positions[p]
            if stage != 2 and target == -1 and not (paused >> at & 1):
                if at == (self.pickup[i] if stage == 0 else self.delivery[i]):
                    result[i] += 1
        return tuple(result)

